import{_ as i,I as E,c as s,o as e,a3 as l,b as n,w as a,a as o,J as d,a4 as A}from"./chunks/framework.BusRvirq.js";const D=JSON.parse('{"title":"고위험 작업 다단계 결재 및 감사 추적 가이드","description":"에이전트의 데이터 수정 및 배포 작업에 대한 위험도별 다자간 순차 승인(HITL) 및 감사 로그 운영 절차","frontmatter":{"title":"고위험 작업 다단계 결재 및 감사 추적 가이드","shortTitle":"다단계 결재 & 감사","category":"운영 가이드","sort":2,"description":"에이전트의 데이터 수정 및 배포 작업에 대한 위험도별 다자간 순차 승인(HITL) 및 감사 로그 운영 절차","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/guide/hitl-approval-operations.html"}]]},"headers":[],"relativePath":"guide/hitl-approval-operations.md","filePath":"ko/guide/hitl-approval-operations.md","lastUpdated":1791239682000}'),C={name:"guide/hitl-approval-operations.md"};function B(g,t,h,_,p,c){const r=E("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="고위험-작업-다단계-결재-및-감사-추적-가이드" tabindex="-1">고위험 작업 다단계 결재 및 감사 추적 가이드 <a class="header-anchor" href="#고위험-작업-다단계-결재-및-감사-추적-가이드" aria-label="Permalink to “고위험 작업 다단계 결재 및 감사 추적 가이드”">​</a></h1><h2 id="_1-작업-위험도-분류-기준-risk-levels" tabindex="-1">1. 작업 위험도 분류 기준 (Risk Levels) <a class="header-anchor" href="#_1-작업-위험도-분류-기준-risk-levels" aria-label="Permalink to “1. 작업 위험도 분류 기준 (Risk Levels)”">​</a></h2><p>에이전트가 호출하는 모든 도구(Tool) 및 비즈니스 액션은 시스템에 미치는 영향도에 따라 4단계의 위험 등급으로 사전 분류되어 관리됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">등급</th><th style="text-align:left;">작업 유형</th><th style="text-align:left;">대상 작업 예시</th><th style="text-align:left;">승인 정책</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Level 1 (안전)</strong></td><td style="text-align:left;">단순 조회 및 리포팅</td><td style="text-align:left;">주문 현황 조회, 로그 검색, RAG 문서 탐색</td><td style="text-align:left;"><strong>무승인 자율 실행</strong> (실행 이력 자동 기록)</td></tr><tr><td style="text-align:center;"><strong>Level 2 (주의)</strong></td><td style="text-align:left;">가역적 설정 변경</td><td style="text-align:left;">크롤링 주기 변경, 캐시 만료, 알림 채널 설정</td><td style="text-align:left;"><strong>단일 담당자 승인</strong> (1인 승인)</td></tr><tr><td style="text-align:center;"><strong>Level 3 (경고)</strong></td><td style="text-align:left;">데이터 변경 및 삭제</td><td style="text-align:left;">회원 정보 수정, 상품 가격 일괄 변경, DB 레코드 삭제</td><td style="text-align:left;"><strong>2단계 순차 결재</strong> (담당자 ➔ 부서장)</td></tr><tr><td style="text-align:center;"><strong>Level 4 (위험)</strong></td><td style="text-align:left;">시스템 전반 영향</td><td style="text-align:left;">프로덕션 신규 버전 배포, DDL 스키마 변경, 대량 환불</td><td style="text-align:left;"><strong>3단계 다자간 결재</strong> (담당자 ➔ CISO ➔ 책임자)</td></tr></tbody></table><hr><h2 id="_2-웹-콘솔-결재-승인-화면-조작-절차" tabindex="-1">2. 웹 콘솔 결재 승인 화면 조작 절차 <a class="header-anchor" href="#_2-웹-콘솔-결재-승인-화면-조작-절차" aria-label="Permalink to “2. 웹 콘솔 결재 승인 화면 조작 절차”">​</a></h2><p>Level 2 이상의 작업이 감지되면 에이전트의 실행이 즉시 일시 중단(PAUSED)되고, 관리자 포털의 결재 대기 목록에 카드가 등록됩니다.</p>',7)),(e(),n(A,null,{default:a(()=>[d(r,{id:"mermaid-92",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20PENDING_APPROVAL%3A%20%EA%B3%A0%EC%9C%84%ED%97%98%20%EC%9E%91%EC%97%85%20%EB%8F%84%EA%B5%AC%20%ED%98%B8%EC%B6%9C%0A%20%20%20%20PENDING_APPROVAL%20--%3E%20IN_REVIEW%3A%20%EA%B4%80%EB%A6%AC%EC%9E%90%20%EC%83%81%EC%84%B8%20%ED%99%94%EB%A9%B4%20%EC%A1%B0%ED%9A%8C%0A%20%20%20%20IN_REVIEW%20--%3E%20APPROVED%3A%201%EC%B0%A8%2F2%EC%B0%A8%20%EC%8A%B9%EC%9D%B8%20%EC%99%84%EB%A3%8C%0A%20%20%20%20IN_REVIEW%20--%3E%20REJECTED%3A%20%EB%B0%98%EB%A0%A4%20%EA%B2%B0%EC%A0%95%0A%20%20%20%20IN_REVIEW%20--%3E%20AMENDMENT_REQUESTED%3A%20%EC%A1%B0%EA%B1%B4%EB%B6%80%20%EC%88%98%EC%A0%95%20%EC%A7%80%EC%8B%9C%0A%20%20%20%20APPROVED%20--%3E%20EXECUTED%3A%20%EB%B0%B1%EC%97%94%EB%93%9C%20%EC%95%88%EC%A0%84%20%EC%8B%A4%ED%96%89%20%EB%B0%8F%20%EC%8A%A4%EB%83%85%EC%83%B7%20%EB%B3%B4%EA%B4%80%0A%20%20%20%20REJECTED%20--%3E%20CANCELLED%3A%20%EC%9E%91%EC%97%85%20%EC%B7%A8%EC%86%8C%20%EB%B0%8F%20%EB%B3%B4%EC%83%81%20%EB%A1%A4%EB%B0%B1%0A%20%20%20%20AMENDMENT_REQUESTED%20--%3E%20PENDING_APPROVAL%3A%20%EC%97%90%EC%9D%B4%EC%A0%84%ED%8A%B8%20%EB%A7%A4%EA%B0%9C%EB%B3%80%EC%88%98%20%EC%88%98%EC%A0%95%20%ED%9B%84%20%EC%9E%AC%EC%A0%9C%EC%B6%9C%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h3 id="단계별-검토-항목" tabindex="-1">단계별 검토 항목 <a class="header-anchor" href="#단계별-검토-항목" aria-label="Permalink to “단계별 검토 항목”">​</a></h3><ol><li><strong>영향 범위(Blast Radius) 확인</strong>: <ul><li>변경 대상 테이블 명칭, 변경 예상 레코드 수량(Row Count)을 확인합니다.</li><li>단일 레코드가 아닌 1,000건 이상의 대량 변경 건인 경우 사유가 타당한지 검토합니다.</li></ul></li><li><strong>사전-사후 Diff 대조</strong>: <ul><li>변경 전(Current State)과 변경 후(Proposed State)의 JSON/SQL 데이터 차이점이 정확한지 확인합니다.</li></ul></li><li><strong>롤백 스냅샷 가용성 검증</strong>: <ul><li>시스템 장애 발생 시 이전 상태로 되돌릴 수 있는 스냅샷 ID가 정상 생성되었는지 표시기를 점검합니다.</li></ul></li></ol><hr><h2 id="_3-관리자-의사결정-액션-가이드" tabindex="-1">3. 관리자 의사결정 액션 가이드 <a class="header-anchor" href="#_3-관리자-의사결정-액션-가이드" aria-label="Permalink to “3. 관리자 의사결정 액션 가이드”">​</a></h2><ul><li><strong>승인 (Approve)</strong>: <ul><li>검토 결과 작업 내용에 이상이 없는 경우 &#39;승인&#39; 버튼을 클릭합니다.</li><li>다자간 결재 건인 경우 다음 승인권자에게 결재선이 순차 인계되며, 최종 승인 시 실제 트랜잭션이 커밋됩니다.</li></ul></li><li><strong>반려 (Reject)</strong>: <ul><li>비즈니스 정책에 위배되거나 데이터 오염 우려가 있는 경우 구체적인 반려 사유를 입력하고 작업을 거절합니다.</li><li>에이전트는 즉시 작업을 중단하고 관련 리소스를 해제합니다.</li></ul></li><li><strong>수정 지시 (Amend)</strong>: <ul><li>방향성은 타당하나 매개변수(예: 가격 할인율, 대상 사용자 범위 등)의 미세 조정이 필요한 경우, 수정 피드백을 작성하여 에이전트에게 재작업을 지시할 수 있습니다.</li></ul></li></ul><hr><h2 id="_4-감사-로그-추적-및-위변조-방지" tabindex="-1">4. 감사 로그 추적 및 위변조 방지 <a class="header-anchor" href="#_4-감사-로그-추적-및-위변조-방지" aria-label="Permalink to “4. 감사 로그 추적 및 위변조 방지”">​</a></h2><p>모든 승인/반려 의사결정 내역은 내부 감사 장부(Audit Ledger)에 영구 저장됩니다:</p><ul><li><strong>기록 항목</strong>: 요청 일시, 실행 에이전트 ID, 승인자 사번 및 IP 주소, 요청 원본 프롬프트, 도구 파라미터 해시값, 최종 실행 결과.</li><li><strong>무결성 보증</strong>: 감사 로그는 타임스탬프 기반의 암호화 해시 체인(SHA-256)으로 상호 결합되어 있어, 데이터베이스 관리자라 할지라도 과거 이력을 임의로 조작하거나 삭제할 수 없습니다.</li></ul>',9))])}const u=i(C,[["render",B]]);export{D as __pageData,u as default};
